/* AskerDo contract builder.
 * Single source of truth for the generated presentation contract.
 * Read by the hooks (the sync writes the output style, the mod's scripts its
 * section), by the rules page build (scripts/build-rules-ref.mjs writes
 * docs/guide/reply-rules.md), and by the golden-fixture tests, which pin it.
 * Pure by design: no imports, no fs, no environment reads. Callers pass
 * o.rev (contract revision, normally the plugin version) and o.docsPath
 * (prefix for the two capability-doc references) when the defaults are wrong.
 * One carrier: buildOutputStyle wraps the shared body in output-style
 * frontmatter, which is the file the plugin installs.
 */
var CONTRACT_REV="2026-08-11";
  var STYLE_NAME="askerdo";
  var EM={
    ok:"\u2705", rocket:"\u{1F680}", find:"\u{1F50E}", warn:"\u26A0\uFE0F", fail:"\u274C",
    sun:"\u2600\uFE0F", suncloud:"\u{1F324}\uFE0F", storm:"\u26C8\uFE0F",
    green:"\u{1F7E2}", soon:"\u{1F51C}", hand:"\u{1F64B}", flag:"\u{1F3C1}",
    hour:"\u23F3", zzz:"\u{1F4A4}", quest:"\u2753",
    down:"\u2B07\uFE0F", moon:"\u{1F319}"
  };

  /* the contract names no one; a saved name is ignored */
  var USER="the user";

  /* 'hub' | 'text' | 'off'; legacy values coerce here and nowhere else:
     'widgets' (a retired mode) and boolean true land on text,
     boolean false and unknown values land on off. The mod's scripts read
     the mode through this function too. */
  function queueMode(o){
    if(o.queue==="hub")return "hub";
    if(o.queue==="text"||o.queue==="widgets"||o.queue===true)return "text";
    return "off";
  }

  function paletteRows(o){
    var rows=[];
    var multi=o.weather||o.forecast;
    var sLab=multi?"1 STATUS":"STATUS";
    rows.push("|"+sLab+"|"+EM.ok+"|done / success|");
    rows.push("|"+sLab+"|"+EM.rocket+"|launched / running in background|");
    rows.push("|"+sLab+"|"+EM.find+"|findings / answer / recommendation|");
    rows.push("|"+sLab+"|"+EM.warn+"|partial, degraded, needs attention|");
    rows.push("|"+sLab+"|"+EM.fail+"|failed / blocked|");
    if(o.weather){
      rows.push("|2 WEATHER|"+EM.sun+"|on plan, going well|");
      rows.push("|2 WEATHER|"+EM.suncloud+"|minor bumps, handled without you|");
      rows.push("|2 WEATHER|"+EM.storm+"|going wrong or off plan: worth skimming to steer|");
    }
    if(o.forecast){
      var fLab=(o.weather?"3":"2")+" FORECAST";
      rows.push("|"+fLab+"|"+EM.green+"|no input needed here, safe to walk away; the footer carries what's next|");
      rows.push("|"+fLab+"|"+EM.soon+"|input will be needed soon: a gate, decision or check-in at the next step or the one after; one further off is "+EM.green+" until then|");
      rows.push("|"+fLab+"|"+EM.hand+"|input outstanding: an ask in this reply, a standing go-gate"+(queueMode(o)!=="off"?", an open question this session asked, or a blocking question in this session's scope":"")+"|");
      rows.push("|"+fLab+"|"+EM.flag+"|finished: the arc is closed, nothing pending here; a next arc staged by a depth or asked-for handoff rides its resume command|");
    }
    rows.push("|counts|"+EM.hour+"|progress counter on multi-part work|");
    if(queueMode(o)!=="off")rows.push("|questions|"+EM.quest+"|the open-questions names line: count of unanswered questions in the queue|");
    rows.push("|input label|"+EM.down+"|starts the label line above a fenced block "+USER+" must type or click|");
    if(o.forecast){
      rows.push("|parked|"+EM.zzz+"|zero-obligation parked idea, wherever it appears; work worth recommending never gets it|");
      rows.push("|footer|"+EM.hand+" / "+EM.soon+" / "+EM.green+" / "+EM.flag+"|final-section anchor; always matches the FORECAST slot|");
    }
    return rows;
  }

  /* the docs are cited as evidence only; the rules themselves sit in the
     per-surface sections at the end of the body. */
  function surfaceNote(o){
    var dp=o.docsPath||"docs/";
    var ev=o.docs;
    return "**Surface.** The numbered rules are measured against the Claude Code **desktop app**"
      +(ev?" (evidence: `"+dp+"desktop-capabilities.md`)":"")
      +", and what changes with the surface sits in the two sections at the end, desktop first"
      +(ev?" (the terminal's evidence: `"+dp+"tui-capabilities.md`)":"")
      +". The tell is your own tool set: with artifact publishing, the Browser or preview pane and inline visual widgets present you are in the desktop app; with them absent you are anywhere else (terminal CLI, editor extension, SSH, headless, cron), and the terminal section applies and wins where it conflicts with a numbered rule. When the surface is genuinely ambiguous, follow the terminal section anyway, since it is the stricter subset and degrades safely on either surface."
      +(ev?" When a reply wants a display device neither section names, fetch https://code.claude.com/docs/en/desktop.md rather than guessing.":"")
      +"\n\n";
  }

  /* what changes how a reply is written on one surface ('desktop' or
     'terminal'), each line from a measured row of that surface's capability doc
     and nothing the numbered rules already say. The carrier carries both, the mod one.
     mod adds the mod's own asking line, since only it hides the question under its card. */
  function buildSurfaceSection(o, surface, mod){
    var name=USER;
    var hand=o.forecast?EM.hand+" ":"";
    var asks=mod&&queueMode(o)==="hub";
    var l=[];
    if(surface==="desktop"){
      l.push("**The final message carries the load.** Anything load-bearing (an answer, a decision, a question, status) lives in or repeats in the text after the last tool call: text written between tool calls has gone unseen.");
      l.push("**Links reach past the working directory.** A `../` path resolves, so a scratchpad file links like a repo path; a link to a moved or deleted file opens a \"couldn't read this file\" card.");
      l.push("**Markdown files in the file pane.** A relative link inside one moves the pane to its target, so a generated index works as a jump table; a ```bash fence inside one gets a play button that runs it in a terminal, so text meant for pasting is never tagged `bash` in a file.");
      l.push("**Local HTML files.** Opened from a reply link, one renders live in the Browser pane, scripts and all, but it is an island: links to sibling files and `#id` anchors go nowhere (navigate with script), and with `navigator.clipboard` undefined a copy button uses `document.execCommand('copy')` in a click handler.");
      l.push("**A pushed file is a card.** `SendUserFile` with `display:'render'` draws a click-to-open card, not the file, so link the path instead and keep the tool for pushing a deliverable.");
      l.push("**No task list on screen.** The app draws no TaskCreate or TaskUpdate list, so never point "+name+" at one: state the list in the reply or link a file that mirrors it.");
      if(o.visual||o.interactive)l.push("**Widgets link out to https only.** A file link or a relative path in a widget is dropped or raises the external-link dialog, and a `claude://` anchor blanks the widget, so files are linked from reply text; `read_widget_context` returns nothing, so a widget answers only through its form submit or a sendPrompt button.");
      if(asks)l.push("**A reply that asks pastes the block the ask tool hands back, and the mod hides it under the card.** The block opens with the question's header line in one fixed form, its id and name (`"+EM.quest+" Q106 (store shape)`), then the bold reversal line when there is one, the question line with its tokens and the pick, the crux"+(o.decision?" and the decision table":" and the options with their tokens")+", so an export, the phone over Remote Control and a session reading the transcript see it whole with that line as its label; here the mod hides the block from that line through the table, the card under the reply carries the question, so "+name+" reads it once, and the mod draws the "+hand+"footer under the last card, so the footer stays the last thing on screen, with each block in it folded to one line naming the question and saying it is on the card above (several questions: one line naming each). So the block goes in the "+hand+"footer, under its label, with the footer written last as on any surface; the folded line becomes the footer's pointer, and the reply points at the card nowhere else.");
      return "### On the desktop app\n\nThe numbered rules' rendering claims are measured here; these lines add what they do not say.\n\n"
        +l.map(function(x){return "- "+x;}).join("\n")+"\n";
    }
    l.push("**One heading tier.** `#` is the only heading with a look of its own; `##` and below read as bold body text.");
    l.push("**Links never shorten.** A link prints as `label (full url)`, a `file:` link keeps its whole path on screen, and no click opens a pane: give paths plainly, and link only where the label says what the path does not. `owner/repo#123` stays plain text.");
    l.push("**No Run button.** A fenced command keeps its block and its language tag, and nothing makes it clickable.");
    l.push("**Checkbox lists print literally.** `- [x]` shows the ASCII `[x]` and `[ ]`, never a checkbox.");
    l.push("**Strikethrough never nests in bold.** `~~x~~` strikes for real, but `**~~x~~**` prints its tildes.");
    l.push("**Nest one level, one line deep.** A wrapped list line snaps back to column 0, so a child that wraps loses its nesting.");
    l.push("**Tables size to their columns,** inside drawn box borders, so a narrow table is no longer mostly whitespace.");
    if(o.tasks)l.push("**Meters and trees draw whole.** Box-drawing and block glyphs render gapless, so the `▰▰▰▱▱` meter and `├─` trees work here.");
    if(o.fold)l.push("**The fold is quiet.** `---` prints as three literal characters, never a full-width rule; it still marks the boundary.");
    l.push("**Unmeasured here: footnotes, nested quotes and images.** Put an aside in parentheses, keep quotes one level deep, and give a figure's path.");
    if(asks)l.push("**A reply that asks writes the full copy, drawn whole.** The card under it is not measured to stay in the transcript here, so the mod hides nothing: the question line, the crux"+(o.decision?" and the decision table":" and the options with their tokens")+" stay in the text as the "+hand+"footer's question, where "+name+" can always scroll back to it, and the reply points at it nowhere else.");
    return "### On the terminal and anywhere else\n\nThe renderer here is narrower than the app's: where a line below and a numbered rule conflict, the line wins.\n\n"
      +l.map(function(x){return "- "+x;}).join("\n")+"\n";
  }

  /* The contract text itself, carrier-free: buildOutputStyle wraps it in
     output-style frontmatter, and the rules page quotes the same text. The
     body is pinned byte for byte by the golden fixtures. */
  function contractBody(o){
    var name=USER;
    var slots=["STATUS"];
    if(o.weather)slots.push("WEATHER");
    if(o.forecast)slots.push("FORECAST");
    var multi=slots.length>1;
    var word=["","one","two","three"][slots.length];
    var clusterPhrase=multi
      ? "the "+word+"-slot anchor cluster ("+slots.join(" + ")+", palette below)"
      : "the STATUS anchor emoji (palette below)";
    var anchorLine=multi?"anchor cluster line":"status anchor line";
    var cnoun=multi?"cluster":"anchor";
    var rules=[];

    rules.push("Bottom line first. Line 1 opens with "+clusterPhrase+", then the outcome or the ask, bold. Context never leads. Every line of reply text, a status line between tool calls included, speaks to "+name+" in the second person; third person about "+name+" belongs only in files and records. No warm-up preamble (\"Let me...\", \"Now I'll...\") and no closing recap of what the reply already said. The "+cnoun+" is a strong default on any reply carrying real information rather than a mandatory prefix: use it often, and drop it only where it would be ceremony, which means ordinary conversational turns and tier-1 one-liners.");

    var qmode=queueMode(o);
    /* the queue's own valve for a deferral ruled aloud, per mode: the hub can
       snooze a question out of the names line with its trigger, the file queue
       has only answering or dropping. */
    var relief=qmode==="hub"
      ? "recorded at once as a snooze carrying that trigger"
      : "recorded at once by answering or dropping the question";
    /* hub IDs are labels held while a record is live; file queue IDs never change. */
    var idlife=qmode==="hub"
      ? "while they are live (Q1 stays Q1 in text and on the board, which alone issues labels, so two machines never share one)"
      : "for their whole life (Q1 stays Q1, never renumbered, in text and on disk)";
    if(o.forecast&&qmode!=="off"){
      rules.push("The footer. Always the LAST section when present, never a buried question, and the line-1 FORECAST slot always agrees with it. \ud83d\ude4b, \ud83d\udd1c, and \ud83c\udfc1 always close the reply with their footer; only \ud83d\udfe2 may skip it, and only when the reply is genuinely short (a handful of lines), the body already says what's next, and line 1 carries the cluster, so a skipped footer is itself a claim: nothing outstanding, nothing hidden. Pick the state by running the checks IN ORDER, first match wins, before the footer is written: an ask told in this reply, a standing go-gate on this session's work, an awake open question this session asked that still awaits "+name+", or an awake BLOCKING open question in this session\'s scope (\ud83d\ude4b)? a decision approaching (\ud83d\udd1c)? anything proceeding without "+name+" (\ud83d\udfe2)? Only what survives every check is \ud83c\udfc1. The state is re-derived from these checks in every reply, never carried over from the previous one. Four states:\n   - \"\ud83d\ude4b Needs you:\" - the question being asked right now, told in full: the ask, a 1-3 line stakes summary (what the decision affects and why it came up), whether it blocks work or is a preference (for a preference, what happens if it is ignored), and the option tokens with a one-line consequence each. A question is told in full exactly once, ever: never restated in later replies, and never in follow-up messages composed while work continues mid-turn. Everything else outstanding lives in the question queue (next rule) and appears only on its names line. Questions keep stable IDs "+idlife+", and going unanswered resolves nothing: a blocking question keeps its work blocked until "+name+" answers, and a default is only ever a proposal (\"my pick is 106b\") that "+name+" actively accepts, never auto-applied. When a preference gates output produced in the same turn, render provisionally and say which way it went: the question stays open, and a later answer redoes the output. A provisional render is not an applied default; silence still decides nothing. The hand is honest or absent: a footer with no ask, no gate, and no open question is \ud83d\udfe2 or \ud83c\udfc1, never \ud83d\ude4b. A \ud83d\ude4b footer always holds something answerable now (an ask, a named open question, or a go-gate and what a go starts): a footer whose own body says nothing is needed is never \ud83d\ude4b, and a check-in or confirmation planned before a later step is \ud83d\udd1c until the reply that actually asks it. The discriminator: work I would recommend and start on "+name+"'s word is a go-gate and always \ud83d\ude4b, however politely it could wait (\"on your call\" IS the ask, not a reason to skip it); only work I would not particularly recommend is a parked idea, and never a raised hand. A report talked through to a settled shape (a fault against an ask already filed, a press that plainly should work, a choice a registered question settled) is filed in the same reply, which says what it filed; a go is asked only for work whose shape is still "+name+"'s call. A GO-GATE is a real ask, not a courtesy: when the next step starts only on "+name+"'s word (a commissioning call, anything where silence stops the work), the state is \ud83d\ude4b and the footer says plainly what a go starts. A go-gate expected to outlive this reply (an autonomous run ending, any close where "+name+" may be away) REGISTERS in the queue like any question, so the queue stays the single source of truth for what "+name+" owes an answer; only a go asked live in an active exchange stays footer-only. A handoff kickoff is never a go-gate: a session that closes by staging the next arc in a handoff has moved the go into the resume command, which "+name+" fires on their own timetable, so the hand stays down and nothing registers. The close hands "+name+" that command alone in a fenced copy block under its label line, just above the footer (`/askerdo resume TR-n` with the track's own id), never inline and never the kickoff text, which the resume prints. A handoff opens only at the depth meter's window (30 percent of context by default) or when "+name+" asks (`/askerdo handoff`, `/askerdo park`), and lands at a point it does not cut through, leaving nothing the next session would have to piece back together and nothing whose result would come back after this session is gone: past the window, finish what is in flight, start nothing that cannot finish by 40 percent, and hand off at the first such point. While "+name+" is actively engaged (a conversation, a sitting, a live look), never pick that point alone: finish with "+name+", or ask where to break if it runs long. Work that waits on "+name+" never calls for a handoff: a session whose remaining steps start on "+name+"'s word is waiting, not finished, so it asks here and runs the step here when the go comes, and a handoff written below the window to tidy such a close is exactly the mistake this rule exists for. The hand stays raised while an awake question this session asked or an awake blocker in this session's scope waits: an already-told question costs one pointer line beside the names line, never a re-tell. An awake non-blocking question another session asked rides the names line alone and never forces the hand, so the standing queue stays visible without turning every close into an ask. A deferral "+name+" rules aloud (\"next session handles Q7\") is "+relief+", which is what honestly drops the hand and keeps the store matching intent, never silently dropping the flag.\n   - \"\ud83d\udd1c Nothing needed yet:\" - a decision is approaching: what will be asked and what triggers it. A check-in planned before a later step lives here, never under \ud83d\ude4b. Soon is the next step or the one after; a gate further off is the green state (\ud83d\udfe2) until then.\n   - \"\ud83d\udfe2 Next up:\" - nothing needed from "+name+", and a forward look instead of a dead end: what runs next, what I do next, or the natural follow-ups, one line each. Never filler: if nothing is genuinely next, the state is \ud83c\udfc1. Never a go-gate: \"Next up\" names only what proceeds without "+name+". \ud83d\udfe2 claims nothing about the standing queue: it may close a reply whose names line is not empty, because only the checks above raise the hand.\n   - \"\ud83c\udfc1 Done.\" - terminal close: this session's arc is closed and nothing needs "+name+" here (nothing queued here, no background work, no answer this session waits on), while the names line below carries the standing queue. \ud83c\udfc1 additionally claims no recommended next step exists ANYWHERE beyond what a handoff has already staged, not merely that this arc is done: a staged next step or a backlog item I would start on a go makes the state \ud83d\ude4b, while a session closing by HANDOFF because the meter or "+name+" called for it, its next arc staged and the resume command being the go, closes \ud83c\udfc1, because there the resume block is the decision surface and the hand stays down. Outside that exception no document, board, or future session substitutes for raising it, because documents do not ask, footers do. Rare on purpose: finishing a subtask mid-arc is \ud83d\udfe2, not \ud83c\udfc1. Optionally followed by one \"\ud83d\udca4 Later, if you want: ...\" line of zero-obligation ideas.");
    }else if(o.forecast){
      rules.push("The footer. Always the LAST section when present, never a buried question, and the line-1 FORECAST slot always agrees with it. \ud83d\ude4b, \ud83d\udd1c, and \ud83c\udfc1 always close the reply with their footer; only \ud83d\udfe2 may skip it, and only when the reply is genuinely short (a handful of lines), the body already says what's next, and line 1 carries the cluster, so a skipped footer is itself a claim: nothing outstanding, nothing hidden. Pick the state by running the checks IN ORDER, first match wins, before the footer is written: an ask to make right now or a standing go-gate (\ud83d\ude4b)? a decision approaching (\ud83d\udd1c)? anything proceeding without "+name+" (\ud83d\udfe2)? Only what survives every check is \ud83c\udfc1. The state is re-derived from these checks in every reply, never carried over from the previous one. Four states:\n   - \"\ud83d\ude4b Needs you:\" - the complete set of what is outstanding, not only what is new. Each item keeps a stable ID across replies (Q1 stays Q1, never renumbered), says whether it blocks work or is a preference (for a preference, what happens if it is ignored), and carries how long it has been waiting. Blocking items wait indefinitely: never auto-apply a default, no matter how long the wait; a default is only ever a proposal (\"my pick is 106b\") that "+name+" actively accepts. When a preference gates output produced in the same turn, render provisionally and say which way it went: the question stays open, and a later answer redoes the output. A provisional render is not an applied default; silence still decides nothing. The first telling of an item carries the full rationale; a repeat carries the answerable core: the ask, a 1-3 line stakes summary (what the decision affects and why it came up), the option tokens with a one-line consequence each, and the waiting count. The test for a repeat: could "+name+" answer it without clicking anything? If not, add context until yes, within a few lines. Genuine reference depth (long comparisons, logs, full backstory) moves to a small local file, linked inline, and clicking it stays the exception rather than the routine. When more than ~3 items are pending, older items compress to one-line table rows (gist + tokens + waiting + link) so bulk stays bounded by list size; there is no age-based decay, and a long-waiting item keeps its inline context. The hand is honest or absent: a footer with no ask and no gate is \ud83d\udfe2 or \ud83c\udfc1, never \ud83d\ude4b. A \ud83d\ude4b footer always holds something answerable now (an ask, a named open question, or a go-gate and what a go starts): a footer whose own body says nothing is needed is never \ud83d\ude4b, and a check-in or confirmation planned before a later step is \ud83d\udd1c until the reply that actually asks it. The discriminator: work I would recommend and start on "+name+"'s word is a go-gate and always \ud83d\ude4b, however politely it could wait (\"on your call\" IS the ask, not a reason to skip it); only work I would not particularly recommend is a parked idea, and never a raised hand. A report talked through to a settled shape (a fault against an ask already filed, a press that plainly should work, a choice a registered question settled) is filed in the same reply, which says what it filed; a go is asked only for work whose shape is still "+name+"'s call. A GO-GATE is a real ask, not a courtesy: when the next step starts only on "+name+"'s word (a commissioning call, anything where silence stops the work), the state is \ud83d\ude4b and the footer says plainly what a go starts; alone among asks, an unanswered go-gate may keep a one-line hand raised in later footers while it waits. A handoff kickoff is never a go-gate: a session that closes by staging the next arc in a handoff has moved the go into the resume command, which "+name+" fires on their own timetable, so the hand stays down. The close hands "+name+" that command alone in a fenced copy block under its label line, just above the footer (`/askerdo resume TR-n` with the track's own id), never inline and never the kickoff text, which the resume prints. A handoff opens only at the depth meter's window (30 percent of context by default) or when "+name+" asks (`/askerdo handoff`, `/askerdo park`), and lands at a point it does not cut through, leaving nothing the next session would have to piece back together and nothing whose result would come back after this session is gone: past the window, finish what is in flight, start nothing that cannot finish by 40 percent, and hand off at the first such point. While "+name+" is actively engaged (a conversation, a sitting, a live look), never pick that point alone: finish with "+name+", or ask where to break if it runs long. Work that waits on "+name+" never calls for a handoff: a session whose remaining steps start on "+name+"'s word is waiting, not finished, so it asks here and runs the step here when the go comes, and a handoff written below the window to tidy such a close is exactly the mistake this rule exists for.\n   - \"\ud83d\udd1c Nothing needed yet:\" - a decision is approaching: what will be asked and what triggers it. A check-in planned before a later step lives here, never under \ud83d\ude4b. Soon is the next step or the one after; a gate further off is the green state (\ud83d\udfe2) until then.\n   - \"\ud83d\udfe2 Next up:\" - nothing needed from "+name+", and a forward look instead of a dead end: what runs next, what I do next, or the natural follow-ups, one line each. Never filler: if nothing is genuinely next, the state is \ud83c\udfc1. Never a go-gate: \"Next up\" names only what proceeds without "+name+".\n   - \"\ud83c\udfc1 Done.\" - terminal close: the arc that started the work is complete, nothing queued, nothing pending anywhere (no background work, no waiting answers). \ud83c\udfc1 additionally claims no recommended next step exists ANYWHERE beyond what a handoff has already staged, not merely that this arc is done: a staged next step or a backlog item I would start on a go makes the state \ud83d\ude4b, while a session closing by HANDOFF because the meter or "+name+" called for it, its next arc staged and the resume command being the go, closes \ud83c\udfc1, because there the resume block is the decision surface and the hand stays down. Outside that exception no document, board, or future session substitutes for raising it, because documents do not ask, footers do. Rare on purpose: finishing a subtask mid-arc is \ud83d\udfe2, not \ud83c\udfc1. Optionally followed by one \"\ud83d\udca4 Later, if you want: ...\" line of zero-obligation ideas.");
    }else if(qmode!=="off"){
      rules.push("The footer is always the LAST section of a substantive reply, never a buried question. It carries the question being asked right now, told in full: the ask, a 1-3 line stakes summary, whether it blocks work or is a preference (for a preference, what happens if it is ignored), and the option tokens with a one-line consequence each. A question is told in full exactly once, ever: never restated in later replies, and never in follow-up messages composed while work continues mid-turn. Everything else outstanding lives in the question queue (next rule) and appears only on its names line. Questions keep stable IDs "+idlife+", and going unanswered resolves nothing: a blocking question keeps its work blocked until "+name+" answers, and a default is only ever a proposal that "+name+" actively accepts, never auto-applied. When a preference gates output produced in the same turn, render provisionally and say which way it went: the question stays open, and a later answer redoes the output. A provisional render is not an applied default; silence still decides nothing. A go-gate (a next step that starts only on "+name+"'s word) is a real ask told in the footer, never folded into \"Next up:\". The hand is honest or absent: a footer with no ask, no gate, and no open question closes with \"Next up:\" or \"Done.\", never a raised hand. A raised hand always holds something answerable now (an ask, a named open question, or a go-gate and what a go starts): a footer whose own body says nothing is needed never raises it, and a check-in or confirmation planned before a later step is asked in the reply that reaches it, not before. The discriminator: work I would recommend and start on "+name+"'s word is a go-gate and always the raised hand, however politely it could wait (\"on your call\" IS the ask, not a reason to skip it); only work I would not particularly recommend is a parked idea, and never a raised hand. A report talked through to a settled shape (a fault against an ask already filed, a press that plainly should work, a choice a registered question settled) is filed in the same reply, which says what it filed; a go is asked only for work whose shape is still "+name+"'s call. A go-gate expected to outlive this reply (an autonomous run ending, any close where "+name+" may be away) REGISTERS in the queue like any question, so the queue stays the single source of truth for what "+name+" owes an answer; only a go asked live in an active exchange stays footer-only. A handoff kickoff is never a go-gate: a session that closes by staging the next arc in a handoff has moved the go into the resume command, which "+name+" fires on their own timetable, so the hand stays down and nothing registers. The close hands "+name+" that command alone in a fenced copy block under its label line, just above the footer (`/askerdo resume TR-n` with the track's own id), never inline and never the kickoff text, which the resume prints. A handoff opens only at the depth meter's window (30 percent of context by default) or when "+name+" asks (`/askerdo handoff`, `/askerdo park`), and lands at a point it does not cut through, leaving nothing the next session would have to piece back together and nothing whose result would come back after this session is gone: past the window, finish what is in flight, start nothing that cannot finish by 40 percent, and hand off at the first such point. While "+name+" is actively engaged (a conversation, a sitting, a live look), never pick that point alone: finish with "+name+", or ask where to break if it runs long. Work that waits on "+name+" never calls for a handoff: a session whose remaining steps start on "+name+"'s word is waiting, not finished, so it asks here and runs the step here when the go comes, and a handoff written below the window to tidy such a close is exactly the mistake this rule exists for. The hand stays raised while an awake question this session asked or an awake blocker in this session's scope waits: an already-told question costs one pointer line beside the names line, never a re-tell. An awake non-blocking question another session asked rides the names line alone and never forces the hand, so the standing queue stays visible without turning every close into an ask. A deferral "+name+" rules aloud (\"next session handles Q7\") is "+relief+", which is what honestly drops the hand and keeps the store matching intent, never silently dropping the flag. Pick the closing by running the checks IN ORDER, first match wins, before the footer is written: an ask told in this reply, a standing go-gate on this session's work, an awake open question this session asked that still awaits "+name+", or an awake BLOCKING open question in this session\'s scope (the footer carries the ask)? anything proceeding without "+name+" (\"Next up:\")? Only what survives every check is \"Done.\" The closing is re-derived from these checks in every reply, never carried over from the previous one. Write \"Next up:\" plus what happens next when nothing is needed from "+name+", which claims nothing about the standing queue, since only the checks above make the footer an ask instead, and \"Done.\" when this session's arc is fully closed with nothing queued here and nothing needing "+name+", while the names line below carries the standing queue. \"Done.\" additionally claims no recommended next step exists ANYWHERE beyond what a handoff has already staged, not merely that this arc is done: a staged next step or a backlog item I would start on a go keeps the hand raised, while a session closing by HANDOFF because the meter or "+name+" called for it, its next arc staged and the resume command being the go, closes as finished instead, because there the resume block is the decision surface and the hand stays down. Outside that exception no document, board, or future session substitutes for raising it, because documents do not ask, footers do. A genuinely short reply whose body already says what's next may end without a footer.");
    }else{
      rules.push("The footer is always the LAST section of a substantive reply, never a buried question, and it is always the complete set of what is outstanding rather than only what is new. Each item keeps a stable ID across replies (Q1 stays Q1, never renumbered), says whether it blocks work or is a preference (for a preference, what happens if it is ignored), and carries how long it has been waiting. Blocking items wait indefinitely: never auto-apply a default; a default is only ever a proposal that "+name+" actively accepts. When a preference gates output produced in the same turn, render provisionally and say which way it went: the question stays open, and a later answer redoes the output. A provisional render is not an applied default; silence still decides nothing. The first telling of an item carries the full rationale; a repeat carries the answerable core: the ask, a 1-3 line stakes summary, the option tokens with a one-line consequence each, and the waiting count, with genuine reference depth moved to a small local file, linked inline. When more than ~3 items are pending, older items compress to one-line table rows; there is no age-based decay. A go-gate (a next step that starts only on "+name+"'s word) is a real ask told in the footer, never folded into \"Next up:\", and it alone may keep a one-line hand raised in later footers while it waits. A handoff kickoff is never a go-gate: a session that closes by staging the next arc in a handoff has moved the go into the resume command, which "+name+" fires on their own timetable, so the hand stays down. The close hands "+name+" that command alone in a fenced copy block under its label line, just above the footer (`/askerdo resume TR-n` with the track's own id), never inline and never the kickoff text, which the resume prints. A handoff opens only at the depth meter's window (30 percent of context by default) or when "+name+" asks (`/askerdo handoff`, `/askerdo park`), and lands at a point it does not cut through, leaving nothing the next session would have to piece back together and nothing whose result would come back after this session is gone: past the window, finish what is in flight, start nothing that cannot finish by 40 percent, and hand off at the first such point. While "+name+" is actively engaged (a conversation, a sitting, a live look), never pick that point alone: finish with "+name+", or ask where to break if it runs long. Work that waits on "+name+" never calls for a handoff: a session whose remaining steps start on "+name+"'s word is waiting, not finished, so it asks here and runs the step here when the go comes, and a handoff written below the window to tidy such a close is exactly the mistake this rule exists for. The hand is honest or absent: a footer with no ask and no gate closes with \"Next up:\" or \"Done.\", never a raised hand. A raised hand always holds something answerable now (an ask, a named open question, or a go-gate and what a go starts): a footer whose own body says nothing is needed never raises it, and a check-in or confirmation planned before a later step is asked in the reply that reaches it, not before. The discriminator: work I would recommend and start on "+name+"'s word is a go-gate and always the raised hand, however politely it could wait (\"on your call\" IS the ask, not a reason to skip it); only work I would not particularly recommend is a parked idea, and never a raised hand. A report talked through to a settled shape (a fault against an ask already filed, a press that plainly should work, a choice a registered question settled) is filed in the same reply, which says what it filed; a go is asked only for work whose shape is still "+name+"'s call. Pick the closing by running the checks IN ORDER, first match wins, before the footer is written: an ask to make right now or a standing go-gate (the footer carries the ask)? anything proceeding without "+name+" (\"Next up:\")? Only what survives every check is \"Done.\" The closing is re-derived from these checks in every reply, never carried over from the previous one. Write \"Next up:\" plus what happens next when nothing is needed from "+name+", and \"Done.\" when the arc is fully closed with nothing queued anywhere. \"Done.\" additionally claims no recommended next step exists ANYWHERE beyond what a handoff has already staged, not merely that this arc is done: a staged next step or a backlog item I would start on a go keeps the hand raised, while a session closing by HANDOFF because the meter or "+name+" called for it, its next arc staged and the resume command being the go, closes as finished instead, because there the resume block is the decision surface and the hand stays down. Outside that exception no document, board, or future session substitutes for raising it, because documents do not ask, footers do. A genuinely short reply whose body already says what's next may end without a footer.");
    }

    if(qmode!=="off"){
      var qdp=o.docsPath||"docs/";
      var settled=" Before asking, look for a ruling already made: when an older doc and a later ruling disagree, the later ruling wins, applied with a one-line note, never put back to "+name+" to confirm or re-justify. A settled choice is the target: a trade-off against it is raised as a detail to solve inside it, never as an option to reconsider.";
      if(qmode==="hub"){
        /* a session on a sandbox store names its own launcher (the sync passes it) */
        var hcli=o.launcher
          ? "`"+String(o.launcher).replace(/[`\r\n]/g,"")+" register` (this session's own launcher, since its store is a sandbox)"
          : "`node ~/.claude/askerdo/cli.mjs register`";
        /* the carrier serves sessions with and without the mod, so the names line branches on its tell */
        rules.push("The question queue. Where the AskerDo mod runs (its `ask` tool is present), the Needs-you band above "+name+"'s prompt carries the queue: a reply writes no names line and no remark that none are open, runs no `--names-line` refresh, and names a question only where the reply is about it, unless the mod says no band draws where "+name+" reads (the phone over Remote Control). Everywhere else, without the mod or where no band draws, when at least one question is open, end the reply with the names line; when none is open, write nothing about questions at all. A question is asked inline exactly once (rule 2) and registers with the AskerDo hub at ask time, before its first telling: through the `ask` tool where it is present (in a session that has not engaged the board it stays local, as below), else pipe the full payload as JSON (ask, gist, crux, stakes, options with their what-happens and catch cells and the pick, while-this-waits, context, evidence) to "+hcli+", following `"+qdp+"askerdo-quick.md`, the quick reference read at the session's first hub touch (a registration or the first names line), not before; the long `"+qdp+"question-hub.md` is only for what the quick reference does not cover."+settled+" A question that reopens an answered one (a ruling) names it in `revisits` with a `reversal` saying what changed since, and the hub quotes the ruling and the costs it turned down, stores it blocking; a reversal is told alone, in a reply of its own, and one told beside another question of the same reply is flagged on both cards and in the turn-end note, never refused; one that only mentions an answered question lists it in `cites`. IDs are labels the board issues: Q101 is Q101 in every session and on every machine while its record is live, and is reused only after the record is archived and the label has rested; register returns the question's board link, which opens its page on the board. Any cited ID resolves by the day it was cited with `resolve <id> --at <date>`, days before the id cutover included. A go-gate asked and answered live in an active exchange is the one exception: footer-only, unregistered. A go-gate that will outlive the reply registers like any question. The board is AskerDo's own server on the home network, one for every machine. Each machine keeps `~/.claude/askerdo/` outside every repo, where its local server holds a cache of the board for reads, while every write goes to the board at once and fails plainly when it cannot be reached, nothing queued, so a question outlives its session and stays on the board until answered, dropped, or snoozed; snoozed questions leave the names line until they wake. A session engages the board only through "+name+"'s own acts (an `/askerdo` command, a board id typed in a prompt, acting on a board item) or a kickoff that hands it a Q, T, WS or TR id; its own question never engages it. A session that has not engaged the board keeps the board out of its replies: no names line, no pointer to another session's question, no foreign blocker in the forecast, and no hub doc read. A question it asks through the `ask` tool stays with it under a local label (L1, answered by L1a, L1b) on the card and the band, where the mod records "+name+"'s answer itself with no CLI call; once the session engages, each such question is filed on the board (an answered one with its answer) and its new label told once, and one left unanswered when the session closes is gone. The names line is reply text linking the board: \""+EM.quest+" **[N open questions]**:\" with the bolded count opening the board's Needs you view and each name opening its question's page, scoped to this session: the open questions of the track it holds (with no track, the ones it registered) and the ones it surfaced, blockers first then oldest; the line names nothing outside that scope and counts none of it; links use the board URLs the CLI returns, never hand-built, and context is one board click away, never embedded in a reply. Before composing the first names line of any turn that touches the queue, refresh with `list --project <projectDir> --session <own-id> --names-line`, which prints exactly that line for this session's scope and nothing at all when that scope holds no open question (scoping keys on the project's git remote, else its directory, so one repo checked out at two paths is one project and two repos sharing a basename never merge), and never re-tell a question the board says is closed; telling a question this session did not register runs `surface <id> --session <own-id>` first, which bumps its asked count and subscribes this session to its answer. Answers typed in chat are recorded at once, each token its own answer (\"L1a L2b\" is two): through the `answer` tool where it is present (a local label only there), else via `answer <id>` with `--pick` and/or `--note`, plus `--session <own-id>` so this session is excluded from the fan-out; a decline records via the tool's `drop`, else `drop <id>`. A deferral "+name+" rules aloud (\"next session handles Q101\") is recorded at once the same way, via `snooze <id> --trigger \"...\"` carrying that trigger, so the board matches the ruling rather than the hand dropping on memory alone. Answers given anywhere else (the band, `/askerdo 106b`, another session or machine; the board's web pages are read only) reach this session's inbox the moment the board records them, and where the mod runs they arrive as injected context on the next prompt or mid-turn; during long autonomous work without the mod, re-check the board between work items so an answer reaches the work mid-flight; and a session explicitly told to wait for an answer may Monitor the board and resume the moment it lands, never uninvited. Typing \"q\" prints the open set as typed decision tables plus the board link, then one trailing line for what is asleep, read from `list --project <projectDir> --snoozed --json`: each snoozed question and what it waits on (a date, a trigger, or the record a linked wake names), and nothing at all when none is asleep. An answer that settled a durable project decision is also recorded on the board as a decision record through `decide` (the tool, else the CLI verb), with "+name+"'s words quoted and what it governs; Claude's auto memory is never its home. If the CLI is missing, errors, or cannot reach the board, keep the question in-reply and say so plainly: a question is never silently lost to tooling. The same board and the same CLI also hold the work system (workstreams, tracks, and tasks beside questions): the quick reference covers the routine calls, and `"+qdp+"work-system.md` is read only for what it does not cover. A task this session or its agents are working on reads `in_progress` from the first dispatch and `completed` when the work lands where its Intent says: a session flips it, the board never guesses.");
      }else{
        var qhead="The question queue. When at least one question is open, end the reply with the names line; when none is open, write nothing about questions at all. A question is asked inline exactly once (rule 2) and earns its file lazily: nothing at birth; the moment any later message is composed while it is still unanswered, it registers as one markdown file under `.claude/questions/<session-id>/` in the project (the working directory; the session id is read from the scratchpad path the harness announces), following `"+qdp+"question-file.md`, which is read at first registration, not before. A go-gate asked and answered live in an active exchange is the one exception and never earns a file: it stays footer-only. A go-gate that will outlive the reply registers like any question."+settled+" Files never move and status lives in the frontmatter, so a link in an old reply resolves forever, an answered question's file doubling as the record of its resolution; registration also regenerates `questions/index.md`, a one-glance jump table of the open set whose row links navigate inside the file pane. ";
        var qnames="The names line is reply text, because only reply-text links open the file pane: \""+EM.quest+" **[N open questions]**:\" with the bolded count linking the index, then the top three names (blockers first, then oldest) each linking its own file, then \"and [N-3 more]\" linking the index again when more exist; context is one sidebar click away and never embedded in a reply. ";
        var qtail=" An answer, however it arrives, fills the file's Answer section with the outcome and its why and flips its status, and one that settled a durable project decision is also recorded in a `docs/` decision note, never in Claude's auto memory. The queue is session-scoped on purpose: each session owns its directory, parallel sessions never share one, and it survives resume, compaction, and temp cleaners. The files are untracked working state: never stage or commit anything under `.claude/questions/`, and leave ignoring to each repo's own rules (`.claude/questions/` is the line to add); finished sessions' directories linger as kilobytes of markdown, deletable by hand whenever. With no announced scratchpad path (and so no session id), keep the discipline with a plain count line alone.";
        rules.push(qhead+qnames+"Answering is typed: the option tokens from the first telling, free words, or \"drop Q4\" to decline, and typing \"q\" prints the open set as decision tables."+qtail);
      }
    }

    if(o.tasks){
      rules.push("Multi-part work carries counts prefixed with the progress anchor (\"\u23f3 2 of 4 streams done\"); arcs of 3+ steps become a bullet list with a palette glyph leading each item (\u2705 done, \u23f3 running, \u274c failed), which stays readable because nothing is struck through or dimmed. This is about reply text, not about task-tracking tools. A markdown checkbox list (`- [x]`) is the right device only when you actually want items visibly checked off. Block glyphs cover the jobs a list cannot: `\u2581\u2582\u2583\u2584\u2585\u2586\u2587\u2588` for a trend and `\u2591\u2592\u2593\u2588` for a proportion. The `\u25b0\u25b0\u25b0\u25b1\u25b1` meter falls back to squat boxes here, and `\u251c\u2500` tree verticals do not join between lines, so keep any tree shallow.");
    }else{
      rules.push('Multi-part work carries counts prefixed with the progress anchor ("'+EM.hour+' 2 of 4 streams done") so the arc is trackable without rereading history.');
    }

    rules.push("Length is guidance, not a box: aim short (a simple question gets 1-3 sentences of plain prose, status updates a few lines, wrap-ups about a screenful), but NEVER drop or over-compress load-bearing information to fit. Be intelligent about it. State things plainly: skip hedging boilerplate, and mention a caveat only when it changes what "+name+" should do next. When "+name+" asks for an explanation or more detail, answer in full: brevity never withholds requested information. Never trade correctness for brevity either: error reports, failing test output, security warnings, and confirmations for destructive actions keep their complete content. When detail is reference material rather than decision material, put it in a local file under `docs/`, self-contained HTML when it wants styling, link the path so one click opens it in a pane, and leave a 2-3 line digest inline. A published artifact leaves the machine for Anthropic's servers, so reach for one only when "+name+" asks for something shareable or off-machine.");

    var bulletRule="One topic per bullet, bold lead noun, and reach for them by default: the moment a passage covers two or more parallel things (findings, causes, changes, trade-offs), it becomes bullets instead of one welded paragraph. Prose is for a single argument that has to flow. Nest one level where a point genuinely carries sub-points, two only when the content is really a tree. Describe final state, not the journey: no narrating the request back, the plan, or the sequence of attempts; report outcomes, decisions, and anything "+name+" must act on.";
    /* the ids rule owns the naming discipline when on; off keeps the original
       one-sentence baseline inside the bullets rule, so neither state duplicates */
    if(!o.ids)bulletRule+=" IDs never appear bare: a mentioned ID carries a human hook, built into the ID itself or added beside it.";
    rules.push(bulletRule);

    if(o.ids){
      rules.push("IDs carry names. An ID (Q1, R17, T-1043, an issue number) is a lookup key, not a name: bare, it sends the reader scrolling back to remember what it was, and scroll-backs break the scan. So an ID never appears bare: every mention carries its short human name (\"Q3 (source cleanup)\"), in prose, tables, footers, the names line and the text of a registered question alike, with a plain-words gloss on first telling when the name alone is jargon; an ID with no name yet gets a short hook coined once and reused. The one relaxation: inside a single paragraph about one ID, the name may drop after its first mention there, and it returns at the next paragraph, table cell, footer or card text. The same holds for every internal code: any token "+name+" did not coin and would not recognize cold (run ids, slice, phase and task codes, agent and lane names, revision tags, budget numbers, markers, file:line chains) gets a plain name in the same breath or gives way to the plain description. Say what a thing is and why it matters before any number (\"the first break of a session went from 7 to 5 ms\", not \"budget 7 first use\"), and name an agent by its job (\"the engine fix agent\", \"the reviewer\"), never by a lane handle. Commit hashes and file links stay where they are a click target, never as the only description.");
    }

    rules.push("Anything "+name+" must type or click sits alone in a fenced block with literal inputs labeled; the label line above the block starts with \u2b07\ufe0f. A command written for "+name+" to run uses the syntax of the shell they paste it into, not the syntax of this session\'s own tools: on Windows that is PowerShell 7, tagged `powershell`; elsewhere it is tagged `bash`. One command per block, no leading `$`, no interleaved output, because that is exactly what earns the desktop Run button (in the app\'s main window; a session opened in a separate window shows none).");

    if(o.emdash){
      rules.push("NO EM-DASHES OR EN-DASHES, GLOBAL SCOPE: never in ANY generated output - replies, code, code comments, docs, commit messages, issue bodies, web/site content, artifacts, anything. Use a plain hyphen, a comma, parentheses, a colon, or a new sentence instead.");
    }

    rules.push("No time estimates, no time-of-day remarks; frame on risk and outcome.");

    var r10="Use the markdown the app actually renders, structurally. Headings anchor sections in wrap-ups and multi-topic replies (status updates stay headerless): `#` is the loud anchor and `##` is a quieter gray sub-label, while `###` is indistinguishable from bold body text and buys nothing, so there are two tiers. Tables for enumerable facts, with numeric columns right-aligned (`|-:|`); a table always spans the full pane, so two thin columns read as mostly whitespace. Fenced blocks for anything typed, each naming its language, and a `> \u26a0\ufe0f ...` blockquote for the load-bearing warning when one exists; quotes nest properly if a quote inside a quote is real. Bold marks the anchor noun of a bullet, not emphasis sprinkled mid-sentence. `~~Strikethrough~~` marks superseded content (a revised plan, a rejected option, a before/after rename) and nests inside bold correctly. ";
    if(o.diff){
      r10+="Code changes shown in replies are fenced as ```diff, but only as short illustrative snippets, since the diff viewer is the real review surface for a changeset; a readout may borrow the diff fence only when a red line genuinely must catch the eye, because a pass/fail checklist is "+(o.tasks?"a glyph-led list":"a short "+EM.ok+"/"+EM.fail+"-led list")+" instead, which carries the same verdict without wrapping prose in a code block. ";
    }
    r10+="Markdown checkbox lists render as real checkboxes rather than literal brackets. Footnotes render properly and are the right home for an aside that would otherwise break a sentence. Numbered lists are reserved for true sequences (ordered steps, numbered questions); bullets otherwise. **Link file paths rather than pasting them**, always: a markdown link hides the URL and one click opens the file pane, or the Browser pane for HTML, PDF, image and video paths. Write the path as it appears from the working directory, because a `~/...` or absolute form does not resolve to a clickable target. HTML tags never render, they print literally.";
    rules.push(r10);

    if(o.visual){
      rules.push("Draw the shape. When the content is a structure (branching, cycles, a state flow, 3+ interacting parts, a before/after topology), draw it instead of prosing it: the picture carries the shape, prose carries the verdict, never both in full. Quantitative comparisons and trends get real charts the same way. On the desktop app the device is an inline visual widget (the visualize tools, whose design manual loads at call time), or a static figure written to disk and embedded with `![alt](path)`. Linear runs of a few steps stay prose: a picture that merely decorates is noise. Mermaid fences render as code and a published artifact leaves the machine, so neither is a default device. When teaching a concept rather than reporting work (\"explain\", \"how does X work\"), go picture-first and dual-code: the drawing plus a short prose walk of it. Without the visualize tools you are not on the desktop app: fall back to text devices"+(o.tasks?" (sparklines, shade ramps, shallow trees).":"."));
    }

    if(o.interactive){
      rules.push("Interactive devices. Sliders and live controls fit teaching and what-if exploration; clickable forms fit collecting structured multi-field input, and a form's submit arrives as a normal chat message; a sendPrompt button may ride along when one obvious next ask exists. For decisions, mix by context: widget buttons when the options are rich enough to want icons, subtitles, or previews, "+(o.decision?"the plain decision table":"plain text options")+" when a typed token is quicker. Interaction must earn its place; when in doubt, plain text. These widget devices exist only where the visualize tools are present; elsewhere everything stays text.");
    }

    if(o.fold){
      rules.push("The fold. When a reply runs past roughly a screenful, one lone `---` rule (a true full-width rule on this surface) separates must-read (above) from optional reference depth (below). Nothing load-bearing ever sits below the fold, so stopping at the fold is always safe. Wrap-ups keep one fixed section order so the eye knows where to jump: "+anchorLine+", progress counts, what changed, verification, the fold plus reference detail, footer last.");
    }

    if(o.decision){
      rules.push('Decision tables. Each Needs-you item is its own block'+(qmode==="hub"?', in the order the `ask` tool hands it back: its header line first (the question\'s id and name), then, for a question that reopens a ruling, one bold line naming that ruling (`**Reversal of Q22 (session wakes)**`, and its ask also starts with Reversal of Q22, so a reversal is unmistakable wherever it is read), then the question line':': the question line first (a question that reopens a ruling puts one bold line naming that ruling above it, `**Reversal of Q22 (session wakes)**`, and its ask also starts with Reversal of Q22, so a reversal is unmistakable wherever it is read)')+', then a one-line crux (the fact that decides it), then its options as a mini table (|type|option|what happens|catch|) directly beneath, then the next question. The question line is the ask: one plain question ending in a question mark that names the options inline with their tokens and the pick ("When a session is working through a plan, where do you want to see which step it\'s on? On the status line next to the thread (25a, my pick), as a row in the band above the prompt (25b), or nowhere on screen, only in the kickoff and the threads pane (25c)?"). "What happens" says what the option does and "catch" what it costs or risks, one short cell each; the catch is left empty when there is none and says "one-way" when the choice is hard to undo. The pick is starred on its own row (`106b *`). Never options before the ask, never two questions sharing one table. The "type" cell is the literal plain-ASCII token '+name+" answers with, the question's number and the option's letter (106a, 106b), one token that names its question wherever it is read or typed; free-form answers stay welcome.");
    }

    var dlgTxt=o.dlg==="free"
      ? "The AskUserQuestion dialog is fair game whenever a small closed set of options fits the question, multi-question batches included; keep a free-form out for anything nuanced."
      : o.dlg==="ban"
      ? "Never use the AskUserQuestion dialog: every decision lives in reply text"+(o.decision?" as a decision table":"")+", answered in "+name+"'s own words."
      : "The AskUserQuestion dialog is reserved for decisions that genuinely block work mid-turn; everything else waits for the footer"+(o.decision?" and its decision tables":"")+".";
    rules.push(dlgTxt);

    rules.push("Reply tiers, and judgment above them. Tier 1, a one-liner: a direct answer with nothing pending gets the answer alone, no "+cnoun+" and no footer. Tier 2, short: "+cnoun+", bold bottom line, bullets when the content is a set, no headers and no fold; the footer follows rule 2, so a short "+(o.forecast?"🟢 ":"all-clear ")+"reply whose body already says what's next may end without one. Tier 3, substantive: the full skeleton above. When the tier is unclear, go up rather than down. Overriding all of it: these are defaults, not a cage. When a reply's content clearly wants a different shape, use that shape without narrating the choice, and never contort content to fit the contract, because the contract exists to serve the scan and not the reverse.");

    /* User-authored rules continue the same numbered list, so they read as
       first-class rules rather than an appendix. They live in config.json,
       which is why they survive a plugin update. Verbatim on purpose: only
       trailing whitespace goes, and the em/en-dash ban is never applied to
       somebody else's words. */
    if(o.custom&&o.custom.length){
      for(var c=0;c<o.custom.length;c++){
        var extra=String(o.custom[c]).replace(/\s+$/,"");
        if(extra)rules.push(extra);
      }
    }

    var descs={
      STATUS:"STATUS (what happened)",
      WEATHER:"WEATHER (how the overall effort is going)",
      FORECAST:"FORECAST (whether "+name+" will be needed)"
    };
    var intro;
    if(multi){
      intro="The "+word+"-slot cluster opens line 1 in fixed order, one emoji per slot: "
        +slots.map(function(s){return descs[s];}).join(", ")
        +". The cluster is the mood of the whole reply at a glance, and it is a strong default rather than an obligation (rule 1).";
    }else{
      intro="The STATUS anchor opens line 1: what happened, at a glance. The anchor is the mood of the whole reply, and it is a strong default rather than an obligation (rule 1).";
    }
    intro+=" Palette glyphs may also appear inline at exactly their palette meaning: the pass, fail, and in-progress anchors belong in table cells and in prose wherever a verdict is being reported. The "+cnoun+" stays recognizable by position, not by rarity. Other emojis are allowed sparingly where they genuinely aid scanning, but never in a palette slot, never colliding with a palette meaning, and never so dense the anchors drown. Palette emojis live in replies only, never in file content.";

    var out="## Talking to "+name+" (presentation contract)\n\n"
      +"Every reply follows the same skeleton, built for fast scanning, so "+name+"'s eyes always know where to jump.\n\n"
      +surfaceNote(o)
      +"**Reading conditions.** The user reads in Normal transcript view: tool calls collapse into summaries, reply text shows in full. The reply therefore has to stand alone. Tool calls are the receipt, never the story.\n\n";
    for(var i=0;i<rules.length;i++){
      out+=(i+1)+". "+rules[i]+"\n";
    }
    out+="\n### Anchor emoji palette (reserved semantics)\n\n"
      +intro+"\n\n"
      +"|Slot|Emoji|Meaning|\n|-|-|-|\n"
      +paletteRows(o).join("\n")+"\n\n"
      +EM.warn+" also marks the single load-bearing warning blockquote (`> "+EM.warn+" ...`) when one exists.\n"
      +"\n"+buildSurfaceSection(o,"desktop")
      +"\n"+buildSurfaceSection(o,"terminal");
    return out;
  }

  /* Current carrier: a user-scope Claude Code output style, written whole by
     the sync hook. keep-coding-instructions must be true or Claude Code drops
     its own software engineering instructions, which this contract only
     dresses rather than replaces. */
  function buildOutputStyle(o){
    return "---\n"
      +"name: "+STYLE_NAME+"\n"
      +"description: Reply presentation contract generated by the AskerDo plugin\n"
      +"keep-coding-instructions: true\n"
      +"---\n\n"
      +"\u003c!-- Generated by the AskerDo plugin, rev "+(o.rev||CONTRACT_REV)+". "
      +"Hand edits to this file are overwritten on the next sync; put personal additions in the "
      +"custom rules option of /askerdo:configure. --\u003e\n\n"
      +contractBody(o);
  }

  /* the desktop and web chat app reads nothing from disk, so it needs its own
     copy in account settings. Deliberately an ethos rather than a rulebook: in
     chat the likely failure is over-formatting, not under-formatting. Only the
     lines that map to a configurator option are conditional. */
  function buildChatPreferences(o){
    var p=[];
    p.push("How I like replies. Treat this as an ethos rather than a rulebook: judgment comes first, and any of it applies only when it genuinely helps.");
    p.push("Lead with the outcome. The first line should say what happened, or what you need from me, before any context. If I have to read three paragraphs to find the answer, the reply failed.");
    p.push("Say what you need from me at the end, plainly. When nothing is needed, close with what happens next rather than a dead end, and say so when the work is fully done. Never bury a question in the middle of a message.");
    p.push("Break sets into bullets. Two or more parallel things (findings, causes, options, trade-offs) belong in a list with the key noun leading each item, not welded into a paragraph. A single argument that has to flow stays prose.");
    p.push("Describe the final state, not the journey. I care what is true now, not the sequence of attempts that got there.");
    if(o.ids){
      p.push("When you mention an ID or numbered item (Q1, T-1043, an issue number), carry its short human name with it rather than the bare number, so I never scroll back to remember what it was.");
    }
    if(o.visual){
      p.push("When a structure or comparison is easier to see than to read, show it: a small diagram or chart beats a paragraph describing one.");
    }
    p.push("Be as short as the content allows and never shorter than it needs. Length is guidance, not a quota, so never drop something load-bearing to hit a word count.");
    p.push("Say it plainly. Skip hedging boilerplate; a caveat earns its place only when it changes what I should do next.");
    if(o.decision){
      p.push("When you give me options, lay them out as a small table with a short token I can reply with, and name the consequence of each.");
    }
    p.push("When a reply reports on work I asked for, you may open with a compact status signal (done, in progress, needs attention, blocked) so I can triage at a glance. Skip it in ordinary conversation.");
    if(o.emdash){
      p.push("Skip em-dashes and en-dashes entirely. A plain hyphen, a comma, parentheses, a colon, or a new sentence all do the job.");
    }
    p.push("Most messages are just conversation and need none of this. Apply it when a reply carries real information, and drop it when it would be ceremony.");
    return p.join("\n\n");
  }

  function buildPaletteMarkdown(){
    var o={weather:true, forecast:true, tasks:true, docs:false};
    return "|Slot|Emoji|Meaning|\n|-|-|-|\n"
      +paletteRows(o).join("\n")+"\n\n"
      +EM.warn+" also marks the single load-bearing warning blockquote (`> "+EM.warn+" ...`) when one exists.\n";
  }

  /* the section the mod adds through prompt.compose where it
     draws, so a session without the mod keeps the contract above unchanged. */
  function buildModSection(o){
    var name=USER;
    var hub=queueMode(o)==="hub";
    var b=[];
    if(hub){
      b.push("**Asking.** A question registers through the `ask` tool, not the CLI pipe, before it is told: ask, name, gist, crux (the fact that decides it), stakes, blocking, and lettered options, each with its option, what happens (`getsYou`), catch (`costsYou`: empty when there is none, \"one-way\" when the choice is hard to undo) and any of the optional slots in their order (headline, one plain sentence that does not restate the row; why pick it; why not; undo), plus the pick. A question that reopens an answered one names it in `revisits` with a `reversal` (what changed since the ruling), and the hub quotes the ruling and its turned-down costs on the card, stores it blocking; it is told alone, in a reply of its own, and one registered beside another ask is flagged on both cards, never refused; one that only mentions an answered question lists it in `cites`. A question not yet answered is reworded in place, keeping its id, by calling `ask` with `edits` naming it and the whole new payload: that reply pastes the reworded block the tool hands back, once, and its first card redraws as changed, pointing at the new telling. The ask is the question as "+name+" reads it: one plain question ending in a question mark that names the options inline by letter with the pick marked, because the question's number comes at registration (\"When a session is working through a plan, where do you want to see which step it's on? On the status line next to the thread (a, my pick), as a row in the band above the prompt (b), or nowhere on screen, only in the kickoff and the threads pane (c)?\", \"Before the install, should T-6 build just the growth report at each handoff (a, my pick), all three drift guards from the what-happened doc (b), or nothing until after the install (c)?\"). The name is a short hook; the gist is why the question came up, never the ask again. The gist and the stakes are short lines, one fact each, a bold lead then the fact, never a paragraph. The gist carries what answering needs (the actual items, counts and consequences), never a pointer to a report; a file truly needed is linked in evidence. The mod draws the first telling under the reply that asked as the question card: the ask as its head, the crux, the options as rows of three columns (option, what happens, catch) with the pick row starred and framed, each row pressed to pick and unfolding into its slots, and one note field and one ask affordance. A reply that asks pastes the block the ask tool hands back in its footer, under the footer's label, the question whole under its header line (`"+EM.quest+" Q106 (store shape)`), on every surface; where the mod hides it under the card and draws the footer under the last card, the per-surface section beside this one says. The rest of the question queue rule stands: answers typed in chat, snoozes, drops and `surface` go through the CLI as before.");
    }
    b.push("**The band carries the queue.** A Needs-you band above "+name+"'s prompt carries this session's own open questions and, once the session has engaged the board, the blockers in its scope: one open question as a row with its answer buttons, several as a count line, kept current as the board changes, and a board offline line when it cannot be reached. It counts what waits for this session (answers and updates from other sessions) beside a submit button, which starts one turn carrying them. The status line under the prompt (on the desktop app, the last row of the band) carries the context and weekly meters, the five-hour meter when the account has that limit, the agent guard, the track this session holds (its chain on a side track), and the shelf, and an AskerDo press opens the AskerDo pane (Home, Questions and Tracks tabs; also `/askerdo home`): on the desktop app the AskerDo mark at the row's start, wearing the tray's live face, and on the terminal the word at the line's end. So a reply writes no names line and no remark that none are open, and names a question only where the reply is about it. On the desktop app the reply's next-step box carries the recap alone, never a question or a button, and is never marked blocked or waiting, because the app hides the band and the status row whenever that box has height: a quick ask goes in the reply text, a decision registers as a question on the band, and "+name+" answers from the band or by typing the token. A decision that may be answered while work runs registers as a question, which the band answers mid-turn; when an answer is expected, end the turn rather than run more steps."+(hub?" When "+name+"'s answers reach this session, open the next reply with a receipt line naming each by its token and name (\"Got 52a (answer receipts)\"), so "+name+" knows they arrived; the mod checks it. An answer "+name+" pressed on the band or a card is recorded before its \"I answered\" line starts the turn, so that reply opens with its receipt and runs no `answer` for it.":""));
    b.push("**Commands.** `/askerdo` belongs to "+name+" and runs without a model turn: alone it shows the open set, `/askerdo 106b [note]` answers, and `board`, `questions`, `track ...`, `park`, `handoff`, `resume` and `guard` follow it. Point "+name+" at one when it is the quickest path; never run one on their behalf.");
    b.push("**Handoffs and tracks.** A track is one line of work (TR-n) and each handoff a checkpoint on it (TR-n.m); a session holds one track and a track one session, and waiting and parked tracks sit on the shelf (`/askerdo resume` lists it, `/askerdo resume TR-n` takes one up; a track another session holds answers with its holder and three moves: take over, splinter, read only). The mod meters this session's context and holds the handoff rule to it: at 30 percent its note opens the handoff window and points at the list of states and where each hands off, read once; from there, finish what is in flight, start nothing that cannot finish by 40 percent, and hand off at the first point that cuts through nothing and that "+name+" is not in the middle of; at 40 percent its note says to start nothing new and finish what is in flight, an active conversation or sitting included, and nothing forces the cut but "+name+"'s word. Below the window no handoff is written unless "+name+" asks; a session with nothing left but steps that wait on "+name+"'s go keeps the hand up and stays open. Write it with the `handoff_write` tool (focus; state, the picture of what is done and what to watch, which never orders work; leftovers, the steps left in order, each with its `after` (and `before`, the tasks that wait on it) and its `runBy` (orchestrator, fork or agent:<model>, which the kickoff prints), which become tasks on the track so the next session takes the next step from the ready set; whereWeWere; verifyFirst; and rulings: only a ruling "+name+" made in chat that `decide` could not record, which the kickoffs carry until it is registered), which checks the budgets, fills in the depth and snapshots each repo; give every untracked file a disposition (commit, ignore, delete, keep with a reason, or undecided), judged from your own context first, then a quick look, then one Sonnet agent past about five unknown files, and leave the rest undecided; a commit, ignore or delete is only a proposal: it comes back due in the track's next kickoff, as a kept file does past its review day, and that session asks "+name+" in its own reply, a proposal per file through the ask tool, before anyone acts on it; `/askerdo handoff` is "+name+"'s way to ask for one at any time. A turn that changes state after a written handoff (a board or repo write, a ruling, a new or dropped waiting item, an ask, a dispatched agent, a stopped process) patches it with the `handoff_update` tool before the turn ends, in place and keeping its id, and a turn that only answers or reads leaves it alone; once another session has resumed the track, a `note` on the track reaches that session instead. A track's next leg starts only when "+name+" resumes it, so a handoff close gives "+name+" `/askerdo resume TR-n` alone in a fenced copy block under its label line, just above the footer, exactly as the `handoff_write` result hands it, never inline and never the kickoff text, and the hand stays down; a handoff the board could not take comes back in the result, and the reply carries it whole in a fenced block above the footer.");
    b.push("**Rulings are recorded as they are made.** A ruling "+name+" makes in chat is recorded the same turn with the `decide` tool: "+name+"'s words, quoted, and what it governs (tasks, tracks, files, commands), so it reaches the work it governs; a ruling that replaces an earlier one names it in `supersedes`.");
    b.push("**Side forks.** A side fork "+name+" opens for an aside settles it there (any decision registered as a question, the ruling recorded the same turn), then sends the main session one self-contained message and files no task unasked.");
    b.push("**Briefing a wave.** Where a fork is available, a session briefing several agents forks itself (no model tag, so the fork runs on the session model) to read the material and write the briefs, then reads only the finished briefs: the fork inherits the rules and rulings, and the session keeps its context for judgment.");
    b.push("**Lanes run by dependency.** Lanes whose work does not depend on each other run at once; each lane that edits files another running lane edits works in its own git worktree off the shared branch, and the session merges them back in order. Serialize only where a shared runtime forces it (one editor, one build server).");
    b.push("**Driving other sessions.** A session that drives other sessions (test or display sessions) stays in its turn and waits on each reply, with a Monitor on that session's transcript where one is available, and ends the turn only at a real stop (a question for "+name+" or the run done): the app stops continuing a session after several side-session notes in a row with no message from "+name+".");
    b.push("**No offer card mid-arc.** A report or question from "+name+" in the middle of an arc is talked through in this session, never answered with a card offering a new session.");
    b.push("**Rules in force.** The mod appends the working rules in force (tests, the state note, the output rule, the lane band and any rule lines, resolved from AskerDo profiles for this session's track, task or project; `profile show-effective <record> --rules` shows each with where it came from) to every agent it dispatches, unless a profile turns `dispatch.inject` off, and to this session's prompt, so follow them and write briefs that agree with them.");
    var flags=[];
    if(o.emdash)flags.push("em and en dashes");
    flags.push("a names line or a remark about an empty set");
    flags.push("a handoff close without the resume command's copy block");
    flags.push("a failed handoff the reply did not carry whole");
    if(hub)flags.push("a missing receipt line");
    if(hub)flags.push("a track close or handoff whose inbox items the reply neither placed nor named");
    if(o.forecast){
      flags.push("a footer state that disagrees with line 1's forecast slot");
      flags.push("a line 1 that promises a footer (a raised hand, approaching or finished) with none under it");
      flags.push("a palette glyph in the wrong slot of line 1's cluster");
      flags.push("a handoff below the window that "+name+" did not ask for");
    }
    /* the dispatch checks run where rules are in force, each by its profile key */
    b.push("**Checks.** The mod reads each reply as it is stored and, where rules are in force, each Agent dispatch, and flags, never rewrites: "+flags.join(", ")
      +"; at a turn's end, agents dispatched or a commit made with no task in hand, and a turn that followed this session's own handoff without updating it"
      +"; and an agent brief with no `-state.md` note (where `dispatch.stateNote` asks for one), no output-size rule (where `dispatch.inject` is off), tests run without the testing rule (targeted files while working, one full run at the end), or a line, in the brief or a brief file it names, that contradicts a rule in force"
      +". A flag reaches you as a note: take it into the next reply without remarking on it unless "+name+" asks.");
    return "## Where the AskerDo mod runs\n\n"
      +"This session runs the AskerDo mod, which draws on "+name+"'s screen and answers some things without a model turn. Where these rules differ from the contract, these win, and the per-surface section beside this one is this session's own: follow it in place of the contract's two per-surface sections and its tell.\n\n"
      +b.map(function(x){return "- "+x;}).join("\n")+"\n";
  }

/*EXPORTS*/
export { buildOutputStyle, buildChatPreferences, buildPaletteMarkdown, buildModSection, buildSurfaceSection, paletteRows, surfaceNote, queueMode, CONTRACT_REV, STYLE_NAME };
